const BY_ID = new Map(PAGES.map((p) => [p.id, p]));
const BY_SLUG = new Map(PAGES.map((p) => [p.slug, p]));

/** Look up a page by workbook id, e.g. 'S-02'. Throws if unknown so typos fail the build. */
export function page(id: string): PageMeta {
  const p = BY_ID.get(id);
  if (!p) throw new Error(`Unknown page id "${id}". Check src/data/pages.ts.`);
  return p;
}

export function pageBySlug(slug: string): PageMeta | undefined {
  return BY_SLUG.get(slug);
}

export function pagesByTemplate(t: TemplateName): PageMeta[] {
  return PAGES.filter((p) => p.template === t);
}

export function pagesInSection(section: string): PageMeta[] {
  return PAGES.filter((p) => p.section === section);
}

/** Direct children of a hub path, e.g. childrenOf('/sectors/') */
export function childrenOf(slug: string): PageMeta[] {
  return PAGES.filter(
    (p) => p.slug !== slug && p.slug.startsWith(slug) &&
      p.slug.slice(slug.length).replace(/\/$/, '').split('/').length === 1,
  );
}

/** Ancestor trail for BreadcrumbList, excluding the page itself. */
export function ancestorsOf(slug: string): PageMeta[] {
  const parts = slug.split('/').filter(Boolean);
  const trail: PageMeta[] = [];
  let acc = '/';
  const home = BY_SLUG.get('/');
  if (home && slug !== '/') trail.push(home);
  for (let i = 0; i < parts.length - 1; i++) {
    acc += parts[i] + '/';
    const p = BY_SLUG.get(acc);
    if (p) trail.push(p);
  }
  return trail;
}

export const TEMPLATES = [...new Set(PAGES.map((p) => p.template))].sort();
